<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{storeToRefs}from'pinia';import{RouterLink,useRoute,useRouter}from'vue-router';import InventorySubnav from '../components/InventorySubnav.vue';import{useInventoryStore}from'../runtime/inventory-store';import type{WarehouseDraft}from'../types';import'./inventory-views.css';const route=useRoute();const router=useRouter();const store=useInventoryStore();const{workspace,saving}=storeToRefs(store);const id=computed(()=>typeof route.params.warehouseId==='string'?route.params.warehouseId:undefined);const form=reactive<WarehouseDraft>({code:'',name:'',type:'physical',status:'enabled',saleProhibited:false,contactName:null,phone:null,provinceCode:null,cityCode:null,districtCode:null,address:null});const error=ref('');onMounted(async()=>{await store.load();const value=workspace.value.warehouses.find(x=>x.id===id.value);if(value)Object.assign(form,value)});async function submit(){error.value='';try{await store.saveWarehouse({...form},id.value);await router.push('/inventory/warehouses')}catch(e){error.value=e instanceof Error?e.message:'保存失败'}}
</script>
<template><section class="inventory-page"><header class="inventory-header"><div><RouterLink to="/inventory/warehouses">← 返回仓库列表</RouterLink><h1>{{id?'编辑仓库':'新增仓库'}}</h1><p>编码和名称企业内唯一；非零库存或启用库位存在时不能禁用。</p></div></header><InventorySubnav/><form class="inventory-panel inventory-form" @submit.prevent="submit"><label>仓库编码<input v-model="form.code" maxlength="40" required></label><label>仓库名称<input v-model="form.name" maxlength="40" required></label><label>仓库类型<select v-model="form.type"><option value="physical">实体仓</option><option value="virtual">虚拟仓</option></select></label><label>状态<select v-model="form.status"><option value="enabled">启用</option><option value="disabled">禁用</option></select></label><label>联系人<input v-model="form.contactName" maxlength="40"></label><label>联系电话<input v-model="form.phone" maxlength="40"></label><label>省编码<input v-model="form.provinceCode" maxlength="40"></label><label>市编码<input v-model="form.cityCode" maxlength="40"></label><label>区编码<input v-model="form.districtCode" maxlength="40"></label><label>禁售仓库<select v-model="form.saleProhibited"><option :value="false">否</option><option :value="true">是</option></select></label><label class="wide">详细地址<input v-model="form.address" maxlength="200"></label><p v-if="error" class="wide inventory-warning" role="alert">{{error}}</p><div class="inventory-form-actions"><RouterLink class="inv-button" to="/inventory/warehouses">取消</RouterLink><button class="inv-button primary" :disabled="saving">{{saving?'保存中…':'保存'}}</button></div></form></section></template>
